#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations.
Open Scope bv_scope.
Import SX2. Import SX2S.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section FXALL.
Context {fx : FPState}.

Tactic Notation "run_blk" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS scr NX false.
Tactic Notation "run_blk_keep" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS scr NX true.

Section Usage.
  Context {AMB : Amb}.
  Variable sp0 : word.
  Variables av envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.

  Variable lim : Z.
  Hypothesis Hva : valid_argv av.
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
    (* LPS 75d69e00: [main_entry] takes the run's whole ProcInput and the mmap base
     in place of (argv, envp, uid, hwcap).  [mkProcInputC] (Amb.v:42) is the very
     input this Section's own conclusion runs -- [in_argv]/[in_envp]/[in_uid]/
     [in_hwcap] of it reduce to exactly the four the old spelling named -- so
     naming it here is the same statement, not a narrower one. *)
  Local Notation INP := (mkProcInputC av envv fs0 stdin0) (only parsing).
  Hypothesis ME : main_entry sp0 rdraw INP mbase tid regs0 mem0.
  (* LPS 727298f3: the launch's channel reader ([Run.valid_input]); the usage message is a write *)
  Hypothesis Hrdr : a_channel_reader = true.
  Hypothesis Hargc : length av <> 2%nat.

  (* [Run.init_config] installs the launch's vDSO draw over [init_model]
     (75d69e00:theories/LinuxProcessSem/Run.v:1426-1430), so the start model this
     file hands to [s1_startup] must carry it too. *)
  Definition model0 : Model :=
    with_tid tid (with_vdso (Vdso.vdso_run_init (ed_vdso rdraw))
      (init_model (segments_reserved RSEGS) brk mbase sp0 lim (mkProcInputC av envv fs0 stdin0))).

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).

  Lemma model0_halted : m_halted model0 = None.
Proof.
ltac2:(KReplay.run1 (kr_t_S1Usage ()) ["FXALL"; "Usage"] "p;1p;2g0000j10Tg000Uj15Tg0013j12Tg001Vj11Tg0028j14Tg002Zj23Tg0034#0#0#0#0#0#0#5#2R0#1%40'3o"). Qed.
  Lemma model0_lazy : m_vm_lazy model0 = [].
Proof.
ltac2:(KReplay.run1 (kr_t_S1Usage ()) ["FXALL"; "Usage"] "p;1p;2g0000j10Tg000Uj16Tg0013j12Tg003Yj21Tg0049j15Tg004Yj14Tg002Zj23Tg0034#0#0#0#0#0#0#6#2R0/10R0#5%40'3o"). Qed.
  Lemma model0_fd2 : fd_lookup (m_fds model0) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)).
Proof.
ltac2:(KReplay.run1 (kr_t_S1Usage ()) ["FXALL"; "Usage"] "p;1p;2p10059p4p70p1005gp4p710p8g001Vj17Tg0000j10Tg000Uj12Tg006Cj11Tg006aj26Tg007Gj15Tg008?j23Tg002Zj24Tg008aR0#7g0034#0R1#0#0#0#0#0#2%11'6#5,30'4o"). Qed.
  Lemma model0_fs : m_fs model0 = fs0.
Proof.
ltac2:(KReplay.run1 (kr_t_S1Usage ()) ["FXALL"; "Usage"] "p;2g002Zj20Tg0059p,3fs0'0o"). Qed.
  Lemma model0_rdr : m_channel_reader model0 = true.
  Proof. exact Hrdr. Qed.

  Lemma a0s_nonul : ~ In (Z_to_bv 8 0) (hd [] av).
  (* LPS 727298f3: text proofs; the recorded ones spelled [main_entry] at the old arity.
     [Proof using] keeps the section variables the recorded proofs used. *)
  Proof using Hva ME Hargc.
    destruct Hva as (Hl & _ & _ & HF & _).
    destruct av as [|a r]; [cbn in Hl; lia|]. cbn [hd]. exact (Forall_inv HF).
  Qed.

  Lemma hd_nth : hd [] av = nth 0 av [].
  Proof using Hva ME Hargc. destruct av; reflexivity. Qed.

  (* LPS 727298f3: argv[0]'s string ends below the stack window's top, from the launch facts
     ([S1Start.argv_str_fits] at this Section's input); [ref_usage]'s recorded proof uses it. *)
  Lemma a0_str_fits :
    (bv_unsigned (cat_argv_ptr (ed_top rdraw) av envv a_execfn 0) + Z.of_nat (length (nth 0 av [])) + 1
       <= sp_window_hi)%Z.
  Proof.
    destruct (me_lau _ _ _ _ _ _ _ ME) as [brk0 Hlau].
    assert (Hk : (0 < length (in_argv INP))%nat) by (change (in_argv INP) with av; destruct Hva as (Hl & _); lia).
    exact (argv_str_fits sp0 mbase brk0 rdraw INP 0 Hvsp Hva Hve (me_vl _ _ _ _ _ _ _ ME) Hlau Hk).
  Qed.

  Lemma umemcpy1_denot : forall vals M, vals_ev vals 0 = sp0 ->
